import type { ImgHTMLAttributes } from "react";
import manifest from "../../public/photos/manifest.json";

type Dim = { width: number; height: number };
export type PhotoMeta = { src: string; webp: string; webp800: string; width?: number; height?: number };

/** Looks up the WebP variants and pixel size generated by `npm run photos`. */
export function photoMeta(src: string): PhotoMeta {
  const m = (manifest as Record<string, Dim>)[src];
  const base = src.replace(/\.(jpe?g|png)$/i, "");
  return { src, webp: `${base}.webp`, webp800: `${base}-800.webp`, width: m?.width, height: m?.height };
}

export function photoSrcSet(p: PhotoMeta) {
  return `${p.webp800} 800w, ${p.webp} ${p.width ?? 1200}w`;
}

type Props = {
  src: string;
  alt: string;
  sizes?: string;
  /** Above-the-fold image: load eagerly at high priority. */
  priority?: boolean;
} & Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "alt" | "srcSet" | "sizes" | "loading">;

/**
 * Responsive photo: WebP with a JPG fallback, intrinsic width/height so the
 * page never shifts while it loads. The <picture> wrapper is display:contents,
 * so the <img> lays out exactly like a bare <img> would.
 */
export default function Photo({ src, alt, sizes = "100vw", priority = false, ...rest }: Props) {
  const p = photoMeta(src);
  return (
    <picture className="contents">
      <source type="image/webp" srcSet={photoSrcSet(p)} sizes={sizes} />
      <img
        src={src}
        alt={alt}
        width={p.width}
        height={p.height}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : undefined}
        decoding="async"
        {...rest}
      />
    </picture>
  );
}
